import{_ as i,o as a,c as o,ak as s}from"./chunks/framework.Dpc0wyhY.js";const g=JSON.parse('{"title":"Conversations","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/messaging/conversations.md","filePath":"generated/grindr-api/messaging/conversations.md"}'),n={name:"grindr-api/messaging/conversations.md"};function t(r,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to “Conversations”">​</a></h1><h2 id="get-conversations" tabindex="-1">Get conversations <a class="header-anchor" href="#get-conversations" aria-label="Permalink to “Get conversations”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p><em>Also <code>POST /v3/inbox</code>, seems to be aliased to v4 now</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/inbox</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>page</code> — 1-based number, pagination, optional</li></ul><p>Body (optional):</p><ul><li><code>unreadOnly</code> — boolean</li><li><code>chemistryOnly</code> — boolean</li><li><code>favoritesOnly</code> — boolean</li><li><code>rightNowOnly</code> — boolean</li><li><code>onlineNowOnly</code> — boolean</li><li><code>distanceMeters</code> — &quot;double&quot; number value or <code>null</code></li><li><code>positions</code> — array of integers, <a href="/grindr-api/users/profiles#sexual-position-id">sexual position IDs</a></li></ul><p>Response:</p><ul><li><code>entries</code> — array of <a href="/grindr-api/messaging/conversations#conversation">Conversation</a></li><li><code>showsFreeHeaderLabel</code> — boolean</li><li><code>totalFullConversations</code> — number, e.g. <code>&quot;5&quot;</code></li><li><code>totalPartialConversations</code> — number, e.g. <code>0</code></li><li><code>maxDisplayLockCount</code> — number, e.g. <code>99</code></li><li><code>nextPage</code> — integer, e.g. <code>2</code></li></ul><h2 id="get-conversations-v3-alias" tabindex="-1">Get conversations (v3 alias) <a class="header-anchor" href="#get-conversations-v3-alias" aria-label="Permalink to “Get conversations (v3 alias)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/inbox</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>page</code> — 1-based number, pagination, optional</li></ul><p>Body (optional):</p><ul><li><code>unreadOnly</code> — boolean</li><li><code>chemistryOnly</code> — boolean</li><li><code>favoritesOnly</code> — boolean</li><li><code>rightNowOnly</code> — boolean</li><li><code>onlineNowOnly</code> — boolean</li><li><code>distanceMeters</code> — &quot;double&quot; number value or <code>null</code></li><li><code>positions</code> — array of integers, <a href="/grindr-api/users/profiles#sexual-position-id">sexual position IDs</a></li></ul><p>Response:</p><ul><li><code>entries</code> — array of <a href="/grindr-api/messaging/conversations#conversation">Conversation</a></li><li><code>showsFreeHeaderLabel</code> — boolean</li><li><code>totalFullConversations</code> — number, e.g. <code>&quot;5&quot;</code></li><li><code>totalPartialConversations</code> — number, e.g. <code>0</code></li><li><code>maxDisplayLockCount</code> — number, e.g. <code>99</code></li><li><code>nextPage</code> — integer, e.g. <code>2</code></li></ul><h2 id="get-conversations-by-ids" tabindex="-1">Get conversations by IDs <a class="header-anchor" href="#get-conversations-by-ids" aria-label="Permalink to “Get conversations by IDs”">​</a></h2><p>Note: in this v1 endpoint, each <code>participants</code> item only includes <code>profileId</code>, <code>primaryMediaHash</code>, <code>lastOnline</code>, and <code>distanceMetres</code>. Fields <code>onlineUntil</code>, <code>position</code>, <code>isInAList</code>, and <code>hasDatingPotential</code> are absent.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/inbox/conversation</span></span></code></pre></div><p>Body:</p><p>Array of <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a>.</p><p>Response:</p><p>Array of <a href="/grindr-api/messaging/conversations#conversationdata">ConversationData</a>.</p><h2 id="delete-a-conversation" tabindex="-1">Delete a conversation <a class="header-anchor" href="#delete-a-conversation" aria-label="Permalink to “Delete a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Deletes the conversation on your side. Does not delete the conversation for the other chat participant.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE /v4/chat/conversation/{conversationId}</span></span></code></pre></div><p>Response:</p><p>Empty.</p><h2 id="pin-a-conversation" tabindex="-1">Pin a conversation <a class="header-anchor" href="#pin-a-conversation" aria-label="Permalink to “Pin a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Affects sorting position in <a href="/grindr-api/messaging/conversations#get-conversations">get conversations</a> endpoint response.</p><p>Requests on nonexistent conversations seem to be affecting them after they have been created.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/conversation/{conversationId}/pin</span></span></code></pre></div><p>Response:</p><p>Empty.</p><h2 id="unpin-a-conversation" tabindex="-1">Unpin a conversation <a class="header-anchor" href="#unpin-a-conversation" aria-label="Permalink to “Unpin a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Affects sorting position in <a href="/grindr-api/messaging/conversations#get-conversations">get conversations</a> endpoint response. Requests on nonexistent conversations seem to be affecting them after they have been created.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/conversation/{conversationId}/unpin</span></span></code></pre></div><p>Response:</p><p>Empty.</p><h2 id="mute-a-conversation" tabindex="-1">Mute a conversation <a class="header-anchor" href="#mute-a-conversation" aria-label="Permalink to “Mute a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requests on nonexistent conversations seem to be affecting them after they have been created.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/push/conversation/{conversationId}/mute</span></span></code></pre></div><p>Response:</p><p>Empty</p><h2 id="unmute-a-conversation" tabindex="-1">Unmute a conversation <a class="header-anchor" href="#unmute-a-conversation" aria-label="Permalink to “Unmute a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requests on nonexistent conversations seem to be affecting them after they have been created.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/push/conversation/{conversationId}/unmute</span></span></code></pre></div><p>Response:</p><p>Empty</p><h2 id="get-shared-media-in-conversation" tabindex="-1">Get shared media in conversation <a class="header-anchor" href="#get-shared-media-in-conversation" aria-label="Permalink to “Get shared media in conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v5/chat/media/shared/images/with-me/{conversationId}</span></span></code></pre></div><p>Response:</p><ul><li><code>images</code> — array of <a href="/grindr-api/messaging/messages#chatimagebody">ChatImageBody</a></li></ul><h2 id="refresh-messages" tabindex="-1">Refresh messages <a class="header-anchor" href="#refresh-messages" aria-label="Permalink to “Refresh messages”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requests the messages with the given message IDs.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/conversation/{conversationId}/message-by-id</span></span></code></pre></div><p>Body:</p><ul><li><code>messageIds</code> — array of strings</li></ul><p>Response:</p><ul><li><code>messages</code> — array of <a href="/grindr-api/messaging/messages#message">Message</a></li></ul><h2 id="mark-messages-as-read" tabindex="-1">Mark messages as read <a class="header-anchor" href="#mark-messages-as-read" aria-label="Permalink to “Mark messages as read”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Regardless of messageId passed, the whole conversation&#39;s <a href="/grindr-api/messaging/conversations#conversation"><code>unreadCount</code></a> will be reset to 0. messageId is taken into account to present the &quot;Read&quot; label to the sender.</p><p>If you&#39;d like to mark the conversation as read but don&#39;t show it to the other participant, you could pass a valid but nonexistent messageId, such as <code>0:00000000-0000-0000-0000-000000000000</code>.</p><p>Invalid messageIds will cause HTTP status 400 Bad Request errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/conversation/{conversationId}/read/{messageId}</span></span></code></pre></div><p>Response:</p><p>Empty.</p><h2 id="ai-chat-suggestions" tabindex="-1">AI chat suggestions <a class="header-anchor" href="#ai-chat-suggestions" aria-label="Permalink to “AI chat suggestions”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/chat/suggestions</span></span></code></pre></div><p>Query:</p><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li></ul><p>Response:</p><ul><li><code>suggestions</code> — array of objects <ul><li><code>id</code> — UUIDv3</li><li><code>text</code> — string</li><li><code>type</code> — string, <code>SAVED_PHRASE</code> | <code>SMART_PHRASE</code></li></ul></li></ul><h2 id="chat-ai-summary-feedback-wip" tabindex="-1">Chat AI summary feedback, WIP <a class="header-anchor" href="#chat-ai-summary-feedback-wip" aria-label="Permalink to “Chat AI summary feedback, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/chat/summary/feedback</span></span></code></pre></div><h2 id="conversation-id" tabindex="-1">Conversation ID <a class="header-anchor" href="#conversation-id" aria-label="Permalink to “Conversation ID”">​</a></h2><p>String with two long integers separated by <code>:</code>, e.g. <code>&quot;12345678:23456789&quot;</code>. Long integers are IDs of <a href="/grindr-api/users/profiles#profile">Profile</a>. The order of these IDs is always from the lower ID to the higher ID, regardless of who started the chat.</p><h2 id="conversationparticipant" tabindex="-1">ConversationParticipant <a class="header-anchor" href="#conversationparticipant" aria-label="Permalink to “ConversationParticipant”">​</a></h2><ul><li><code>profileId</code> — integer, <a href="/grindr-api/users/profiles#profilemin">Profile ID</a></li><li><code>primaryMediaHash</code> — string or <code>null</code>, see <a href="/grindr-api/media/public-cdn-files">Media -&gt; Public CDN files</a></li><li><code>lastOnline</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>onlineUntil</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>distanceMetres</code> — float number or <code>null</code></li><li><code>position</code> — <a href="/grindr-api/users/profiles#sexual-position-id">Sexual position ID</a> or <code>null</code></li><li><code>isInAList</code> — boolean</li><li><code>hasDatingPotential</code> — boolean</li></ul><h2 id="conversationpreview" tabindex="-1">ConversationPreview <a class="header-anchor" href="#conversationpreview" aria-label="Permalink to “ConversationPreview”">​</a></h2><ul><li><code>conversationId</code> — object <ul><li><code>value</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li></ul></li><li><code>messageId</code> — see <a href="/grindr-api/messaging/messages#message">Message</a> for format</li><li><code>chat1MessageId</code> — string with UUIDv4, second part of <code>messageId</code></li><li><code>senderId</code> — <a href="/grindr-api/users/profiles#profilemin">Profile ID</a></li><li><code>type</code> — <a href="/grindr-api/messaging/messages#message-type">Message type</a></li><li><code>chat1Type</code> — <a href="/grindr-api/messaging/messages#chat1messagetype">Chat1MessageType</a></li><li><code>text</code> — string or <code>null</code></li><li><code>url</code> — unknown, appears to be null</li><li><code>lat</code> — unknown, appears to be null</li><li><code>lon</code> — unknown, appears to be null</li><li><code>albumId</code> — integer, appears to be null</li><li><code>albumContentId</code> — unknown, appears to be null</li><li><code>albumContentReply</code> — unknown, appears to be null</li><li><code>duration</code> — unknown, appears to be null</li><li><code>imageHash</code> — string or <code>null</code></li><li><code>photoContentReply</code> — unknown, appears to be null</li><li><code>rightNowStatus</code> — <a href="/grindr-api/right-now#rightnowattributionstatus">RightNowAttributionStatus</a>, Right Now attribution status. Added in app 26.11.0 under key <code>rightNowStatus</code> (distinct from <code>rightNow</code>). or <code>null</code>, optional</li></ul><h2 id="conversationdata" tabindex="-1">ConversationData <a class="header-anchor" href="#conversationdata" aria-label="Permalink to “ConversationData”">​</a></h2><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>name</code> — string, profile name, may be an empty string, e.g. <code>&quot;&quot;</code></li><li><code>participants</code> — array of <a href="/grindr-api/messaging/conversations#conversationparticipant">ConversationParticipant</a></li><li><code>lastActivityTimestamp</code> — unix timestamp in milliseconds</li><li><code>unreadCount</code> — integer</li><li><code>preview</code> — <a href="/grindr-api/messaging/conversations#conversationpreview">ConversationPreview</a></li><li><code>muted</code> — boolean</li><li><code>pinned</code> — boolean</li><li><code>favorite</code> — boolean</li><li><code>context</code> — unknown or <code>null</code></li><li><code>onlineUntil</code> — unknown, <code>null</code> on the conversation; use <a href="/grindr-api/messaging/conversations#conversationparticipant">ConversationParticipant</a>&#39;s <code>onlineUntil</code> instead.</li><li><code>translatable</code> — boolean</li><li><code>rightNow</code> — string, e.g. <code>&quot;NOT_ACTIVE&quot;</code></li><li><code>hasUnreadThrob</code> — boolean</li></ul><h2 id="conversation" tabindex="-1">Conversation <a class="header-anchor" href="#conversation" aria-label="Permalink to “Conversation”">​</a></h2><p>Conversation object.</p><ul><li><code>type</code> — string, e.g. <code>&quot;full_conversation_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/messaging/conversations#conversationdata">ConversationData</a></li></ul><h2 id="inboxfilterrequest" tabindex="-1">InboxFilterRequest <a class="header-anchor" href="#inboxfilterrequest" aria-label="Permalink to “InboxFilterRequest”">​</a></h2><ul><li><code>unreadOnly</code> — boolean</li><li><code>chemistryOnly</code> — boolean</li><li><code>favoritesOnly</code> — boolean</li><li><code>rightNowOnly</code> — boolean</li><li><code>onlineNowOnly</code> — boolean</li><li><code>distanceMeters</code> — &quot;double&quot; number value or <code>null</code></li><li><code>positions</code> — array of integers, <a href="/grindr-api/users/profiles#sexual-position-id">sexual position IDs</a></li></ul><h2 id="inboxresponse" tabindex="-1">InboxResponse <a class="header-anchor" href="#inboxresponse" aria-label="Permalink to “InboxResponse”">​</a></h2><ul><li><code>entries</code> — array of <a href="/grindr-api/messaging/conversations#conversation">Conversation</a></li><li><code>showsFreeHeaderLabel</code> — boolean</li><li><code>totalFullConversations</code> — number, e.g. <code>&quot;5&quot;</code></li><li><code>totalPartialConversations</code> — number, e.g. <code>0</code></li><li><code>maxDisplayLockCount</code> — number, e.g. <code>99</code></li><li><code>nextPage</code> — integer, e.g. <code>2</code></li></ul><h2 id="conversationprofilemini" tabindex="-1">ConversationProfileMini <a class="header-anchor" href="#conversationprofilemini" aria-label="Permalink to “ConversationProfileMini”">​</a></h2><ul><li><code>profileId</code> — long integer</li><li><code>name</code> — string</li><li><code>mediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a> or <code>null</code></li><li><code>onlineUntil</code> — unknown or <code>null</code></li><li><code>distance</code> — number or <code>null</code></li><li><code>showDistance</code> — boolean</li></ul><h2 id="chatsuggestionsresponse" tabindex="-1">ChatSuggestionsResponse <a class="header-anchor" href="#chatsuggestionsresponse" aria-label="Permalink to “ChatSuggestionsResponse”">​</a></h2><ul><li><code>suggestions</code> — array of objects <ul><li><code>id</code> — UUIDv3</li><li><code>text</code> — string</li><li><code>type</code> — string, <code>SAVED_PHRASE</code> | <code>SMART_PHRASE</code></li></ul></li></ul>',113)])])}const u=i(n,[["render",t]]);export{g as __pageData,u as default};
